      {
        "type": "paragraph",
        "snippet": "You can check your train PNR status directly through the Indian Railways PNR Enquiry portal.",
        "snippet_links": [
          {
            "text": "Indian Railways PNR Enquiry",
            "link": "https://www.indianrail.gov.in/enquiry/PNR/PnrEnquiry.html?locale=en"
          }
        ],
        "snippet_highlighted_words": [
          "through the Indian Railways PNR Enquiry portal"
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "heading",
        "snippet": "Ways to Check PNR Status"
      },
      {
        "type": "heading",
        "snippet": "1. Official Website"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Go to the Indian Railways PNR Enquiry website."
          },
          {
            "snippet": "Type your 10-digit PNR number (found at the top left of your ticket)."
          },
          {
            "snippet": "Complete the simple captcha or submit to view your current booking status, coach, and berth details."
          }
        ],
        "reference_indexes": [
          0,
          1,
          2
        ]
      },
      {
        "type": "heading",
        "snippet": "2. By SMS"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Send a text message from your phone."
          },
          {
            "snippet": "Type PNR <10-digit PNR number> (for example: PNR 1234567890)."
          },
          {
            "snippet": "Send it to 139."
          }
        ],
        "reference_indexes": [
          1,
          3
        ]
      },
      {
        "type": "heading",
        "snippet": "3. By Phone Call"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Dial 139 from your mobile phone."
          },
          {
            "snippet": "Follow the automated voice prompts to enter your 10-digit PNR number."
          }
        ],
        "reference_indexes": [
          4,
          5
        ]
      },
      {
        "type": "heading",
        "snippet": "4. Via WhatsApp"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Send your 10-digit PNR number to the official Indian Railways WhatsApp enquiry service to get updates instantly."
          }
        ],
        "reference_indexes": [
          4
        ]
      },
      {
        "type": "heading",
        "snippet": "5. Mobile Apps"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Use authorized apps like ConfirmTkt PNR Status or other train apps like RailYatri, Paytm, or redRail by redBus.",
            "snippet_links": [
              {
                "text": "ConfirmTkt PNR Status",
                "link": "https://www.confirmtkt.com/pnr-status"
              },
              {
                "text": "redBus",
                "link": "https://www.redbus.in/railways/pnr-status"
              }
            ]
          }
        ],
        "reference_indexes": [
          3,
          5,
          6,
          7
        ]
      },
      {
        "type": "paragraph",
        "snippet": "If you want, tell me your PNR status abbreviation (like RAC, WL, or GNWL), and I can explain what it means for your chances of getting a confirmed seat.",
        "reference_indexes": [
          8
        ]
      }
